/**
 * How a one-off payment — severance, a bonus, a leave payout — divides into the
 * parts the estimate taxes differently. Pure and config-driven: the caps, rates,
 * and the genuine-redundancy tax-free amount all come from the financial year's
 * `TaxYearConfig`, so nothing here is hardcoded to a year.
 *
 * Splitting a payment is about the employment-termination caps alone. Turning the
 * concessional part into the offset that delivers its capped rate needs the year's
 * marginal brackets, so `oneOffConcessionOffset` lives with them in `index.ts`.
 */

import type { Money, TaxYearConfig } from './index.ts'

/**
 * How a one-off payment is taxed.
 *
 * - `ordinary` — assessable in full at marginal rates. A bonus, commission, or
 *   back-pay.
 * - `genuineRedundancy` — a redundancy payment. A tax-free amount computed from
 *   completed years of service is excluded from assessable income entirely; the
 *   excess is an employment-termination payment, and being an EXCLUDED payment it is
 *   bounded by the ETP cap alone.
 * - `employmentTermination` — an ETP that is not a genuine redundancy: a golden
 *   handshake, or a payment in lieu of notice. A NON-EXCLUDED payment, so the bound
 *   is the lesser of the ETP cap and the whole-of-income cap net of the member's
 *   other taxable income.
 * - `unusedLeave` — unused annual or long service leave paid out on a genuine
 *   redundancy. Not an ETP: assessable in full, but the tax on it is capped at a
 *   flat maximum rate.
 */
export type OneOffTaxTreatment =
  'ordinary' | 'genuineRedundancy' | 'employmentTermination' | 'unusedLeave'

/** A single one-off payment for a member, with the concession that applies to it. */
export interface OneOffPaymentInput {
  readonly treatment: OneOffTaxTreatment
  readonly amountCents: Money
  /**
   * Completed years of service, read by `genuineRedundancy` alone. Absent reads as
   * none, and a fractional or negative figure is floored to whole completed years at
   * or above zero.
   */
  readonly yearsOfService?: number
  /**
   * Whether the member was at or above the year's preservation age on the payment
   * date. Absent reads as false — the higher of the two concessional rates.
   */
  readonly atPreservationAge?: boolean
}

/** How one payment splits into the parts the estimate treats differently. */
export interface OneOffPaymentSplit {
  /** Excluded from assessable income entirely; nil for every treatment but a genuine redundancy. */
  readonly taxFreeCents: Money
  /** Included in taxable income, at marginal rates before the concession offset. */
  readonly assessableCents: Money
  /** The part of the assessable amount the capped `concessionalRate` applies to. */
  readonly concessionalCents: Money
  /** The capped rate, excluding the Medicare levy (see `EmploymentTerminationConfig`). */
  readonly concessionalRate: number
}

/** One already-split concession: a concessional amount and the capped rate it bears. */
export interface OneOffConcession {
  readonly concessionalCents: Money
  readonly rate: number
}

/**
 * Splits one payment into its tax-free, assessable, and concessional parts under
 * the treatment it carries. `otherTaxableIncomeCents` is the member's other taxable
 * income for the year, which the whole-of-income cap on a non-excluded ETP is
 * measured net of; the other three treatments ignore it.
 *
 * A genuine redundancy's excess above the ETP cap is assessable but NOT concessional:
 * the ATO taxes it at `aboveCapRate`, which the top marginal bracket already reaches
 * at the incomes at which the cap binds, so it is left to the brackets.
 */
export function splitOneOffPayment(
  payment: OneOffPaymentInput,
  otherTaxableIncomeCents: Money,
  config: TaxYearConfig,
): OneOffPaymentSplit {
  const termination = config.employmentTermination
  const concessionalRate = payment.atPreservationAge
    ? termination.atPreservationAgeRate
    : termination.belowPreservationAgeRate
  const { amountCents } = payment
  switch (payment.treatment) {
    case 'genuineRedundancy': {
      const { baseLimitCents, perYearOfServiceCents } = termination.genuineRedundancy
      const completedYears = Math.floor(Math.max(0, payment.yearsOfService ?? 0))
      const taxFreeLimitCents = baseLimitCents + completedYears * perYearOfServiceCents
      const taxFreeCents = Math.min(amountCents, taxFreeLimitCents)
      const assessableCents = amountCents - taxFreeCents
      return {
        taxFreeCents,
        assessableCents,
        concessionalCents: Math.min(assessableCents, termination.capCents),
        concessionalRate,
      }
    }
    case 'employmentTermination': {
      const headroomCents = Math.max(0, termination.wholeOfIncomeCapCents - otherTaxableIncomeCents)
      return {
        taxFreeCents: 0,
        assessableCents: amountCents,
        concessionalCents: Math.min(amountCents, termination.capCents, headroomCents),
        concessionalRate,
      }
    }
    case 'unusedLeave':
      return {
        taxFreeCents: 0,
        assessableCents: amountCents,
        concessionalCents: amountCents,
        concessionalRate: termination.unusedLeaveMaxRate,
      }
    case 'ordinary':
      return {
        taxFreeCents: 0,
        assessableCents: amountCents,
        concessionalCents: 0,
        concessionalRate: 0,
      }
  }
}
